static uint32_t tint(const Appearance& a, unsigned x, unsigned y) {
  if (a.look == 0) return a.color;
  if (a.look == 2) return 0x40E866;
  static const uint32_t stops[5][6] = {
    {0xFFBC77, 0xEF6CA7, 0x9673ED},
    {0x70E4BD, 0x5DBEEC, 0x7671EF},
    {0x82E5AC, 0x8EA2FF, 0xE984D4},
    {0xFF4040, 0xFFDB38, 0x40E866, 0x38C9FF, 0x725CFF, 0xEF54CD},
    {0xFF4545, 0xFFDB38, 0x40E866}
  };
  unsigned coordinate = a.direction == 1 ? y : a.direction == 2 ? x+y : x;
  unsigned denominator = a.direction == 2 ? 30 : 15;
  unsigned count = a.gradient == 3 ? 6 : 3;
  unsigned pos = coordinate * (count-1) * 255 / denominator;
  if (a.animate) {
    // Mirror the palette to close the loop without a color jump at the wrap.
    uint32_t position = coordinate * 32768U / denominator;
    uint32_t wrapped = (position + 65536U - a.phase) % 65536U;
    uint32_t fraction = wrapped <= 32768U ? wrapped : 65536U - wrapped;
    pos = fraction * (count-1) * 255U / 32768U;
  }
  unsigned index = min(pos / 255, count-2);
  return color_blend(stops[a.gradient][index], stops[a.gradient][index+1], pos-index*255);
}

// Tint the composed frame, not the effect's working buffer (rain trails use that buffer).
static void draw() {
  static uint32_t lastFrame = millis();
  uint32_t now = millis();
  uint32_t elapsed = min(uint32_t(250), uint32_t(now - lastFrame));
  lastFrame = now;
  int mode = modeIndex();
  if (!active || mode < 0 || !strip.isMatrix || Segment::maxWidth != 16 || Segment::maxHeight != 16) return;
  Appearance& a = appearances[mode];
  if (a.animate && a.look == 1 && bri > 0) {
    static const uint32_t periods[] = {120000, 60000, 30000, 15000, 6000};
    uint32_t period = periods[a.animationSpeed-1];
    uint32_t progress = elapsed * 65536U + a.phaseRemainder;
    a.phase = (a.phase + progress / period) % 65536U;
    a.phaseRemainder = progress % period;
  }
  const Segment& segment = strip.getMainSegment();
  uint32_t primary = segment.colors[0];
  uint8_t primaryLevel = max(R(primary), max(G(primary), B(primary)));
  for (unsigned y=0; y<16; y++) for (unsigned x=0; x<16; x++) {
    uint32_t c = strip.getPixelColorXY(x,y);
    uint8_t level = max(R(c), max(G(c), B(c)));
    // The upstream Matrix effect stores falling heads in a row-major bit map.
    // Use it rather than white-pixel detection: primary color now represents the UI color.
    unsigned pixel = y*16+x;
    bool head = mode == 3 && segment.data && segment.dataSize() >= 32
      && (segment.data[pixel >> 3] & (1U << (pixel & 7)));
    // Clock/text brightness comes from the primary color. Avoid applying that
    // brightness twice when tinting, including dark custom colors.
    if ((mode == 0 || mode == 1 || head) && primaryLevel > 0)
      level = min(255U, unsigned(level) * 255U / primaryLevel);
    uint32_t target = head ? 0xFFFFFF : tint(a,x,y);
    strip.setPixelColor(y*16+x, color_blend(BLACK, target, level));
  }
}

static void serve(AsyncWebServerRequest* request) {
  AsyncWebServerResponse* response = request->beginResponse_P(200, "text/html", ICON256_PAGE, sizeof(ICON256_PAGE));
  response->addHeader("Content-Encoding", "gzip");
  response->addHeader("Cache-Control", "no-cache");
  request->send(response);
}

static void setup() {
  server.on("/icon256", HTTP_GET, serve);
  // Registered before initServer(). Let upstream handle explicit advanced URLs.
  server.on("/", HTTP_GET, serve).setFilter([](AsyncWebServerRequest* request) {
    return !request->hasArg("advanced") && !request->hasArg("sliders");
  });
}
